# Chapter 16: IBM Model 1 (Brown et al. 1993), trained by EM from scratch on a tiny parallel corpus.
# t[e][f] = P(English word e | foreign word f). Each English word is generated by one foreign word
# (or by NULL), chosen uniformly; EM finds the translation table without being told any alignments.
import math
from collections import defaultdict

pairs = [("das haus ist klein", "the house is small"),
         ("das haus ist alt", "the house is old"),
         ("das buch ist klein", "the book is small"),
         ("ein buch", "a book"),
         ("ein haus", "a house"),
         ("das buch", "the book")]
pairs = [(["NULL"] + f.split(), e.split()) for f, e in pairs]
E = sorted({w for _, e in pairs for w in e})
F = sorted({w for f, _ in pairs for w in f})
t = {e: {f: 1 / len(E) for f in F} for e in E}            # start uniform: no idea what means what


def log_likelihood():
    total = 0.0
    for f, e in pairs:
        for ew in e:
            total += math.log(sum(t[ew][fw] for fw in f) / len(f))
    return total


print("iteration  log-likelihood   t(house|haus)  t(the|das)  t(book|buch)  t(small|klein)  t(is|ist)")
for it in range(0, 21):
    if it in (0, 1, 2, 3, 5, 10, 20):
        print(f"{it:9d}  {log_likelihood():14.4f}   {t['house']['haus']:13.4f}  {t['the']['das']:10.4f}"
              f"  {t['book']['buch']:12.4f}  {t['small']['klein']:14.4f}  {t['is']['ist']:9.4f}")
    if it == 20:
        break
    count, total = defaultdict(float), defaultdict(float)
    for f, e in pairs:                                     # E-step: expected alignment counts
        for ew in e:
            z = sum(t[ew][fw] for fw in f)
            for fw in f:
                c = t[ew][fw] / z                          # P(e word is aligned to this f word)
                count[(ew, fw)] += c
                total[fw] += c
    for ew in E:                                           # M-step: renormalise the counts
        for fw in F:
            t[ew][fw] = count[(ew, fw)] / total[fw] if total[fw] else 0.0

f, e = pairs[0]
print("\nmost probable alignment of 'the house is small' to 'NULL das haus ist klein':")
print("  " + ", ".join(f"{ew} <- {max(f, key=lambda fw: t[ew][fw])}" for ew in e))
print("translation table rows (P(e | f) above 0.01):")
for fw in ("das", "ein", "alt", "NULL"):
    row = sorted(((t[ew][fw], ew) for ew in E if t[ew][fw] > 0.01), reverse=True)
    print(f"  {fw:5s}: " + ", ".join(f"{ew} {p:.3f}" for p, ew in row))
